function validate([message, limit]) {
  if (typeof message !== 'string' || message.length < 1 || message.length > 10000) return 'message needs 1 to 10^4 characters.';
  if (!/^[a-z ]+$/.test(message)) return 'message may contain only lowercase letters and spaces.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 10000) return 'limit is an integer from 1 to 10^4.';
  return null;
}

