function splitMessage(message, limit) {
  const n = message.length;
  const digits = (x) => String(x).length;
  let indexDigits = 0;
  for (let parts = 1; parts <= n; parts++) {
    indexDigits += digits(parts);
    if (3 + 2 * digits(parts) >= limit) {
      return [];
    }
    const capacity = parts * (limit - 3 - digits(parts)) - indexDigits;
    if (capacity < n) {
      continue;
    }
    const result = [];
    let start = 0;
    for (let index = 1; index <= parts; index++) {
      const suffix = `<${index}/${parts}>`;
      const take = limit - suffix.length;
      result.push(message.slice(start, start + take) + suffix);
      start += take;
    }
    return result;
  }
  return [];
}

