function splitMessage(message, limit) {
  // Try each piece count in turn; every piece but the last is forced to be full, so simulate it.
  for (let total = 1; total <= message.length + 2; total++) {
    const pieces = [];
    let used = 0;
    let ok = true;
    for (let a = 1; a < total && ok; a++) {
      const tag = '<' + a + '/' + total + '>';
      const room = limit - tag.length;
      if (room < 0 || used + room > message.length) ok = false;
      else { pieces.push(message.substring(used, used + room) + tag); used += room; }
    }
    if (!ok) continue;
    const lastTag = '<' + total + '/' + total + '>';
    const rest = message.substring(used);
    if (rest.length + lastTag.length > limit) continue;
    pieces.push(rest + lastTag);
    if (pieces.map(p => p.slice(0, p.lastIndexOf('<'))).join('') === message) return pieces;
  }
  return [];
}

