function generate(rand, size) {
  const letters = 'abcde ';
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 30);
  const message = Array.from({ length: n }, () => letters[Math.floor(rand() * letters.length)]).join('');
  let limit;
  if (size === 'large') {
    const choices = [9, 10, 11, 12, 15, 20, 40, 100, 1000, 10000];
    limit = choices[Math.floor(rand() * choices.length)];
  } else {
    limit = 1 + Math.floor(rand() * 16);
  }
  return [message, limit];
}
